try {
  for (const category of ['sale', 'featured']) {
    await page.goto('http://127.0.0.1:3010/')
    await page.waitForTimeout(2200)
    await page.evaluate(() => {
      window.__loadingSeen = false
      window.__loadingObserver = new MutationObserver(() => {
        if (document.querySelector('main:visible')?.textContent?.includes('Loading category...')) window.__loadingSeen = true
      })
      window.__loadingObserver.observe(document.body, { childList: true, subtree: true, characterData: true })
    })
    const start = Date.now()
    await page.locator("'`a[href="/catalog?category=${category}"]`).click()
    await page.waitForURL(`**/catalog?category=${category}`)
    await page.locator('"'main:visible section li').first().waitFor()
    const elapsedMs = Date.now() - start
    const result = await page.evaluate(() => {
      window.__loadingObserver.disconnect()
      return { loadingSeen: window.__loadingSeen }
    })
    console.log(JSON.stringify({ category, elapsedMs, ...result }))
  }
} finally {
  await browser.close()
}
